1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    padding: 2rem 1rem;
12	    font: 16px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
13	    background: #f5f5f4;
14	    color: #1c1917;
15	  }
16	  main { max-width: 32rem; margin: 0 auto; }
17	  h1 { margin: 0 0 1rem; font-size: 1.5rem; }
18	  form { display: flex; gap: 0.5rem; }
19	  input[type="text"] {
20	    flex: 1;
21	    min-width: 0;
22	    padding: 0.6rem 0.75rem;
23	    font: inherit;
24	    border: 1px solid #d6d3d1;
25	    border-radius: 6px;
26	    background: #fff;
27	  }
28	  button {
29	    padding: 0.6rem 1rem;
30	    font: inherit;
31	    border: 0;
32	    border-radius: 6px;
33	    background: #1c1917;
34	    color: #fff;
35	    cursor: pointer;
36	  }
37	  ul { list-style: none; margin: 1rem 0 0; padding: 0; }
38	  li {
39	    display: flex;
40	    align-items: center;
41	    gap: 0.5rem;
42	    padding: 0.6rem 0.75rem;
43	    margin-bottom: 0.5rem;
44	    background: #fff;
45	    border: 1px solid #e7e5e4;
46	    border-radius: 6px;
47	  }
48	  li span { flex: 1; overflow-wrap: anywhere; }
49	  li button { background: transparent; color: #b91c1c; padding: 0.25rem 0.5rem; }
50	  li button:hover { background: #fee2e2; }
51	  li input[type="checkbox"] { width: 1.1rem; height: 1.1rem; margin: 0; cursor: pointer; }
52	  li[data-completed="true"] span { color: #a8a29e; text-decoration: line-through; }
53	  input[type="date"], select {
54	    padding: 0.5rem;
55	    font: inherit;
56	    border: 1px solid #d6d3d1;
57	    border-radius: 6px;
58	    background: #fff;
59	  }
60	  li .due { flex: none; font-size: 0.85rem; color: #57534e; }
61	  li[data-overdue="true"] { border-color: #fca5a5; background: #fef2f2; }
62	  li[data-overdue="true"] .due { color: #b91c1c; font-weight: 600; }
63	  /* [REQ-006] Priority shown as plain text, no colour, so only overdue is highlighted. */
64	  li .priority { flex: none; font-size: 0.85rem; color: #57534e; }
65	  .filters { display: flex; gap: 0.5rem; margin-top: 1rem; }
66	  .filters button { background: transparent; color: #1c1917; border: 1px solid #d6d3d1; padding: 0.35rem 0.75rem; }
67	  .filters button[aria-pressed="true"] { background: #1c1917; color: #fff; border-color: #1c1917; }
68	</style>
69	</head>
70	<body>
71	<main>
72	  <h1>Todos</h1>
73	  <form id="todo-form">
74	    <input type="text" data-testid="todo-input" placeholder="What needs doing?" autocomplete="off" aria-label="New todo">
75	    <input type="date" data-testid="todo-due" aria-label="Due date (optional)">
76	    <select data-testid="todo-priority" aria-label="Priority">
77	      <option value="low">Low</option>
78	      <option value="med" selected>Med</option>
79	      <option value="high">High</option>
80	    </select>
81	    <button type="submit" data-testid="todo-add">Add</button>
82	  </form>
83	  <div class="filters" role="group" aria-label="Filter todos">
84	    <button type="button" data-testid="filter-all" data-filter="all" aria-pressed="true">All</button>
85	    <button type="button" data-testid="filter-active" data-filter="active" aria-pressed="false">Active</button>
86	    <button type="button" data-testid="filter-completed" data-filter="completed" aria-pressed="false">Completed</button>
87	  </div>
88	  <ul data-testid="todo-list"></ul>
89	</main>
90	<script>
91	(function () {
92	  var STORAGE_KEY = 'todos';
93	  var form = document.getElementById('todo-form');
94	  var input = document.querySelector('[data-testid="todo-input"]');
95	  var list = document.querySelector('[data-testid="todo-list"]');
96	  var dueInput = document.querySelector('[data-testid="todo-due"]');
97	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
98	
99	  // [REQ-001]
100	  function makeId() {
101	    if (window.crypto && typeof window.crypto.randomUUID === 'function') {
102	      return window.crypto.randomUUID();
103	    }
104	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
105	  }
106	
107	  // [REQ-001]
108	  function loadTodos() {
109	    try {
110	      var parsed = JSON.parse(localStorage.getItem(STORAGE_KEY));
111	      return Array.isArray(parsed) ? parsed : [];
112	    } catch (e) {
113	      return [];
114	    }
115	  }
116	
117	  // [REQ-001]
118	  function saveTodos() {
119	    try {
120	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
121	    } catch (e) {}
122	  }
123	
124	  var todos = loadTodos();
125	  var filter = 'all';
126	  var filterButtons = document.querySelectorAll('[data-filter]');
127	
128	  // [REQ-002] Active todos first, then completed.
129	  // [REQ-005] Within each group: high, then med, then low; same priority keeps insertion order.
130	  function orderedTodos() {
131	    var result = [];
132	    [false, true].forEach(function (completed) {
133	      ['high', 'med', 'low'].forEach(function (p) {
134	        todos.forEach(function (t) {
135	          if (!!t.completed === completed && normalizePriority(t.priority) === p) result.push(t);
136	        });
137	      });
138	    });
139	    return result;
140	  }
141	
142	  // [REQ-003] Today's LOCAL calendar date as YYYY-MM-DD (never via UTC).
143	  function todayLocal() {
144	    var d = new Date();
145	    var m = d.getMonth() + 1;
146	    var day = d.getDate();
147	    return d.getFullYear() + '-' + (m < 10 ? '0' : '') + m + '-' + (day < 10 ? '0' : '') + day;
148	  }
149	
150	  // [REQ-003] Accept only a plain YYYY-MM-DD string; anything else means no due date.
151	  function normalizeDue(value) {
152	    return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : '';
153	  }
154	
155	  // [REQ-003] Overdue = due date strictly before today's local date. Date-only string compare.
156	  function isOverdue(todo, today) {
157	    var due = normalizeDue(todo.due);
158	    return due !== '' && due < today;
159	  }
160	
161	  // [REQ-004] Only low, med or high; anything else (including older todos) is med.
162	  function normalizePriority(value) {
163	    return value === 'low' || value === 'high' ? value : 'med';
164	  }
165	
166	  // [REQ-002]
167	  function isVisible(todo) {
168	    if (filter === 'active') return !todo.completed;
169	    if (filter === 'completed') return !!todo.completed;
170	    return true;
171	  }
172	
173	  // [REQ-001]
174	  function render() {
175	    list.textContent = '';
176	    filterButtons.forEach(function (btn) {
177	      btn.setAttribute('aria-pressed', String(btn.getAttribute('data-filter') === filter));
178	    });
179	    var today = todayLocal();
180	    orderedTodos().filter(isVisible).forEach(function (todo) {
181	      var li = document.createElement('li');
182	      li.setAttribute('data-testid', 'todo-item');
183	      li.setAttribute('data-id', todo.id);
184	      li.setAttribute('data-completed', String(!!todo.completed));
185	      li.setAttribute('data-overdue', String(isOverdue(todo, today)));
186	      li.setAttribute('data-priority', normalizePriority(todo.priority)); // [REQ-004]
187	
188	      var toggle = document.createElement('input');
189	      toggle.type = 'checkbox';
190	      toggle.setAttribute('data-testid', 'todo-toggle');
191	      toggle.setAttribute('aria-label', 'Mark complete');
192	      toggle.checked = !!todo.completed;
193	      toggle.addEventListener('change', function () { toggleTodo(todo.id); });
194	      li.appendChild(toggle);
195	
196	      var text = document.createElement('span');
197	      text.setAttribute('data-testid', 'todo-text');
198	      text.textContent = todo.text;
199	
200	      var del = document.createElement('button');
201	      del.type = 'button';
202	      del.setAttribute('data-testid', 'todo-delete');
203	      del.setAttribute('aria-label', 'Delete todo');
204	      del.textContent = 'Delete';
205	      del.addEventListener('click', function () { deleteTodo(todo.id); });
206	
207	      li.appendChild(text);
208	
209	      // [REQ-006] Priority as an uncoloured text label.
210	      var priorityEl = document.createElement('span');
211	      priorityEl.className = 'priority';
212	      priorityEl.textContent = { low: 'Low', med: 'Med', high: 'High' }[normalizePriority(todo.priority)];
213	      li.appendChild(priorityEl);
214	
215	      // [REQ-003] Show the stored string as-is so no timezone shift can occur.
216	      var due = normalizeDue(todo.due);
217	      if (due) {
218	        var dueEl = document.createElement('span');
219	        dueEl.className = 'due';
220	        dueEl.setAttribute('data-testid', 'todo-due-date');
221	        dueEl.textContent = 'Due ' + due;
222	        li.appendChild(dueEl);
223	      }
224	
225	      li.appendChild(del);
226	      list.appendChild(li);
227	    });
228	  }
229	
230	  // [REQ-001]
231	  function addTodo(text, due, priority) {
232	    text = text.trim();
233	    if (!text) return;
234	    // [REQ-003] due is optional, stored as a YYYY-MM-DD string or ''.
235	    todos.push({ id: makeId(), text: text, createdAt: Date.now(), completed: false, due: normalizeDue(due), priority: normalizePriority(priority) }); // [REQ-004]
236	    saveTodos();
237	    render();
238	  }
239	
240	  // [REQ-002]
241	  function toggleTodo(id) {
242	    todos.forEach(function (t) {
243	      if (t.id === id) t.completed = !t.completed;
244	    });
245	    saveTodos();
246	    render();
247	  }
248	
249	  // [REQ-002]
250	  function setFilter(value) {
251	    filter = value;
252	    render();
253	  }
254	
255	  filterButtons.forEach(function (btn) {
256	    btn.addEventListener('click', function () { setFilter(btn.getAttribute('data-filter')); });
257	  });
258	
259	  // [REQ-001]
260	  function deleteTodo(id) {
261	    todos = todos.filter(function (t) { return t.id !== id; });
262	    saveTodos();
263	    render();
264	  }
265	
266	  form.addEventListener('submit', function (e) {
267	    e.preventDefault();
268	    addTodo(input.value, dueInput.value, priorityInput.value);
269	    input.value = '';
270	    dueInput.value = '';
271	    priorityInput.value = 'med';
272	    input.focus();
273	  });
274	
275	  // [REQ-003] Refresh overdue state when the page returns after the date may have changed.
276	  document.addEventListener('visibilitychange', function () {
277	    if (!document.hidden) render();
278	  });
279	
280	  render();
281	})();
282	</script>
283	</body>
284	</html>
